import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Integration Events and Business Events","description":"","frontmatter":{},"headers":[],"relativePath":"events/integration-events-and-business-events.md","filePath":"events/integration-events-and-business-events.md"}`),a={name:`events/integration-events-and-business-events.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="integration-events-and-business-events" tabindex="-1">Integration Events and Business Events <a class="header-anchor" href="#integration-events-and-business-events" aria-label="Permalink to “Integration Events and Business Events”">​</a></h1><p>Business Central supports two important custom event types: <strong>Integration Events</strong> and <strong>Business Events</strong>.</p><p>Both allow developers to publish events that other AL objects can subscribe to and respond to.</p><h2 id="integration-events" tabindex="-1">Integration Events <a class="header-anchor" href="#integration-events" aria-label="Permalink to “Integration Events”">​</a></h2><p>An Integration Event is an event published by AL code to provide an extension point for other parts of an application or other extensions.</p><p>It allows developers to introduce additional functionality without modifying the original application code.</p><p><strong>Example:</strong></p><p>Suppose we have a process that creates a customer.</p><p>We could publish an Integration Event after the customer is created. Another extension could subscribe to that event and send a welcome email.</p><p>Integration Events:</p><ul><li>Allow extensions to hook into existing application functionality.</li><li>Are useful for customization and extensibility.</li><li>Can expose implementation details, such as specific tables and fields.</li><li>Do not carry the same long-term compatibility commitment as Business Events.</li></ul><h2 id="business-events" tabindex="-1">Business Events <a class="header-anchor" href="#business-events" aria-label="Permalink to “Business Events”">​</a></h2><p>A Business Event represents a meaningful occurrence in a business process.</p><p>It communicates <em>what happened</em> rather than the technical details of how it happened.</p><p><strong>Example:</strong></p><p>A sales order has been posted.</p><p>We could publish a Business Event called <code>OnSalesOrderPosted</code>.</p><p>Other components could subscribe to this event and perform actions such as updating another system or initiating another business process.</p><p>Business Events:</p><ul><li>Represent meaningful business occurrences.</li><li>Are designed around business processes rather than implementation details.</li><li>Provide a more stable contract for subscribers.</li><li>Should ideally remain compatible across future application releases.</li></ul><h2 id="key-differences" tabindex="-1">Key Differences <a class="header-anchor" href="#key-differences" aria-label="Permalink to “Key Differences”">​</a></h2><table tabindex="0"><thead><tr><th>Integration Events</th><th>Business Events</th></tr></thead><tbody><tr><td>Primarily provide extension points.</td><td>Represent meaningful business occurrences.</td></tr><tr><td>Can expose implementation details.</td><td>Should avoid exposing implementation details.</td></tr><tr><td>Don&#39;t carry the same compatibility commitment.</td><td>Carry an expectation of long-term stability.</td></tr><tr><td>Useful for application extensibility.</td><td>Useful for business process communication and integrations.</td></tr></tbody></table><h2 id="declaring-events-in-al" tabindex="-1">Declaring Events in AL <a class="header-anchor" href="#declaring-events-in-al" aria-label="Permalink to “Declaring Events in AL”">​</a></h2><p>Both event types are declared using attributes placed above a procedure.</p><p><strong>Integration Event:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[IntegrationEvent(false, false)]</span></span>
<span class="line"><span>procedure OnCustomerCreated(CustomerNo: Code[20])</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p><strong>Business Event:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[BusinessEvent(false)]</span></span>
<span class="line"><span>procedure OnSalesOrderPosted(OrderNo: Code[20])</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Notice:</p><ul><li><code>[IntegrationEvent(...)]</code> identifies an Integration Event publisher.</li><li><code>[BusinessEvent(...)]</code> identifies a Business Event publisher.</li><li>The procedure declares the event and its parameters.</li></ul><p>These publisher procedures don&#39;t contain business logic. They are declarations of events.</p><p><strong>Important:</strong> Declaring an event does not automatically raise it. Your application must call the publisher procedure for subscribers to receive the event.</p><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to “Key Takeaway”">​</a></h2><p>Think of Integration Events as <strong>extension points</strong> and Business Events as <strong>stable notifications of meaningful business occurrences</strong>.</p><p>Both support loose coupling and extensibility, but Business Events have a stronger commitment to long-term compatibility.</p>`,35)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};